<!doctype html><html lang="es"><head><meta charset="utf-8"><style>@page{margin:28px}body{font-family:DejaVu Sans,sans-serif;color:#173b33}.ticket{border:2px solid #173b33;border-radius:15px;padding:25px}.head{background:#103a31;color:#fff;padding:15px 18px}.head h1{margin:0;font-size:24px}.label{font-size:10px;color:#678078;text-transform:uppercase}.passenger h2{margin:5px 0}.grid{display:table;width:100%;margin-top:17px}.cell{display:table-cell;width:33%;padding:11px;border:1px solid #dce8e3}.value{font-size:13px;font-weight:bold}.qr{display:table;width:100%;margin-top:20px}.qr div{display:table-cell;vertical-align:middle}.qr img{width:145px;height:145px}.code{padding:10px;background:#eef5f2;font-size:11px}</style></head><body><main class="ticket"><header class="head"><h1>NavegaYA · {{$isAir?'Boleto aéreo':'Boleto fluvial'}}</h1><small>Estado: CONFIRMADO</small></header><section class="passenger"><span class="label">Pasajero</span><h2>{{$seat->passenger_name}}</h2><strong>DNI o documento: {{$seat->document_number ?: 'No registrado'}}</strong></section><div class="grid"><div class="cell"><span class="label">Origen</span><br><span class="value">{{$isAir?$route->origin_city:$route->originPort->city}}</span></div><div class="cell"><span class="label">Destino</span><br><span class="value">{{$isAir?$route->destination_city:$route->destinationPort->city}}</span></div><div class="cell"><span class="label">Salida</span><br><span class="value">{{$trip->departure_at->format('d/m/Y · H:i')}} h</span></div></div><div class="grid"><div class="cell"><span class="label">Empresa / RUC</span><br><span class="value">{{$company->commercial_name ?: $company->legal_name}}<br>RUC {{$company->ruc ?: 'No registrado'}}</span></div><div class="cell"><span class="label">{{$isAir?'Aeronave':'Embarcación'}}</span><br><span class="value">{{$vehicle->name}}</span></div><div class="cell"><span class="label">Asiento</span><br><span class="value">{{$isAir?$seat->aircraftSeat->code:$seat->seat->code}}</span></div></div><div class="qr"><div style="width:165px"><img src="{{$qrDataUri}}"></div><div><strong>Presenta este QR al abordar.</strong><br>Reserva {{$reservation->code}}<br>Boleto {{$ticket->code}}</div></div><p class="code">Identificador seguro: {{$ticket->boarding_token}}</p></main></body></html>
